			Imported:     true,
			CheckpointID: info.CheckpointID,
			SessionID:    info.SessionID,
			SessionCount: info.SessionCount,
			SessionIDs:   info.SessionIDs,
			Agent:        info.Agent,
		}
		point.SessionPrompt = point.Message
		points = append(points, point)
	}
	return points
}

